FROM "date_dim" WHERE "date_dim"."d_same_day_ly" <= 2484252 LIMIT 23;

SELECT "store_returns"."sr_ticket_number", "store_returns"."sr_return_tax"
FROM "store_returns" WHERE "store_returns"."sr_reversed_charge" != 231.87648649108698 LIMIT 14;

SELECT "catalog_returns"."cr_returned_date_sk", "catalog_returns"."cr_order_number"
FROM "catalog_returns" WHERE "catalog_returns"."cr_item_sk" = 8360 LIMIT 92;

SELECT "ship_mode"."sm_carrier", "ship_mode"."sm_ship_mode_sk"
FROM "ship_mode" WHERE "ship_mode"."sm_ship_mode_id" = 'AAAAAAAACBAAAAAA' LIMIT 17;

SELECT "warehouse"."w_warehouse_sq_ft", "warehouse"."w_street_type", "warehouse"."w_county", "warehouse"."w_warehouse_id"
FROM "warehouse" WHERE "warehouse"."w_street_type" != 'Parkway        ' AND "warehouse"."w_street_number" != '651       ' LIMIT 36;

SELECT "inventory"."inv_date_sk", "inventory"."inv_warehouse_sk", "inventory"."inv_warehouse_sk", "inventory"."inv_quantity_on_hand", "inventory"."inv_date_sk"
FROM "inventory" WHERE "inventory"."inv_date_sk" >= 2451713 LIMIT 88;

SELECT "customer_demographics"."cd_dep_count", "customer_demographics"."cd_gender", "customer_demographics"."cd_demo_sk", "customer_demographics"."cd_education_status", "customer_demographics"."cd_marital_status"
FROM "customer_demographics" WHERE "customer_demographics"."cd_marital_status" != 'D' AND "customer_demographics"."cd_dep_college_count" >= 5 AND "customer_demographics"."cd_marital_status" != 'M' LIMIT 5;

SELECT "household_demographics"."hd_income_band_sk", "household_demographics"."hd_dep_count", "household_demographics"."hd_demo_sk", "household_demographics"."hd_income_band_sk", "household_demographics"."hd_buy_potential"
FROM "household_demographics" WHERE "household_demographics"."hd_vehicle_count" = 3 LIMIT 19;

SELECT "customer_demographics"."cd_demo_sk", "customer_demographics"."cd_demo_sk", "customer_demographics"."cd_dep_count", "customer_demographics"."cd_marital_status", "customer_demographics"."cd_marital_status"
FROM "customer_demographics" WHERE "customer_demographics"."cd_gender" = 'M' LIMIT 70;

